import { config } from "./config";

// Exact artist and track for YouTube's auto-generated "- Topic" uploads, from their description (#26):
//   "Provided to YouTube by <label>", then "Track · Artist", ..., "Auto-generated by YouTube."
// YouTube Data API videos.list, 1 quota unit a song; its terms allow 30 days' caching, this keeps the session's in memory

const API = "https://www.googleapis.com/youtube/v3/videos";
const TIMEOUT_MS = 3000; // ms per lookup

export interface YouTubeSong {
  title: string;
  artist: string;
}

/** The "Track · Artist · Artist" line of an auto-generated description, or null */
export function parseAutoGenerated(description: string): YouTubeSong | null {
  if (!/Auto-generated by YouTube\.?\s*$/i.test(description.trim()) || !/^Provided to YouTube by /im.test(description)) return null;
  const line = description.split(/\r?\n/).map((l) => l.trim()).find((l) => l.includes(" · "));
  if (!line) return null;
  const [title, ...artists] = line.split(" · ").map((s) => s.trim()).filter(Boolean);
  if (!title || !artists.length) return null;
  return { title, artist: artists.join(", ") };
}

const cache = new Map<string, YouTubeSong | null>();

/** The song an auto-generated upload names, or null (no key, not auto-generated, or the API failed) */
export async function songFromYouTube(videoId: string | undefined): Promise<YouTubeSong | null> {
  if (!config.youtubeApiKey || !videoId || !/^[\w-]{11}$/.test(videoId)) return null;
  if (cache.has(videoId)) return cache.get(videoId) ?? null;
  try {
    const url = `${API}?${new URLSearchParams({ part: "snippet", id: videoId, key: config.youtubeApiKey })}`;
    const res = await fetch(url, { signal: AbortSignal.timeout(TIMEOUT_MS) });
    // Never log the URL: it holds the key
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = (await res.json()) as { items?: Array<{ snippet?: { description?: string } }> };
    const song = parseAutoGenerated(data.items?.[0]?.snippet?.description ?? "");
    if (song) console.log(`[YouTube] ${videoId} is "${song.title}" by ${song.artist} (auto-generated upload)`);
    cache.set(videoId, song);
    return song;
  } catch (err) {
    // Not cached: the next request for this video tries again
    console.warn(`[YouTube] Couldn't read video ${videoId}: ${err instanceof Error ? err.message : err}`);
    return null;
  }
}
